def generate_category_questions(category_dict, category_name, level, count):
    """Generate questions for any category"""
    templates = category_dict.get(level, [])
    questions = []

    for i in range(count):
        template = templates[i % len(templates)]
        text, answers, correct_idx, hint = template

        questions.append({
            'id': f'{category_name[:3].lower()}-l{level}-{i+1:03d}',
            'category': category_name,
            'level': level,
            'text': text,
            'answers': answers,
            'correct_idx': correct_idx,
            'hint': hint
        })

    return questions

def main():
    output_file = '/home/user/roadmapplan/quiz-questions-5000-educational.csv'

    all_questions = []

    # Generate 500 questions per category (100 per level × 5 levels)
    categories = [
        (BIOLOGY_QUESTIONS, 'Biology'),
        (GEOGRAPHY_QUESTIONS, 'Geography'),
        (MATH_QUESTIONS, 'Math'),
        (SCIENCE_QUESTIONS, 'Science'),
        (TECHNOLOGY_QUESTIONS, 'Technology'),
        (HISTORY_QUESTIONS, 'History'),
    ]

    for category_dict, category_name in categories:
        for level in range(1, 6):
            questions = generate_category_questions(category_dict, category_name, level, 100)
            all_questions.extend(questions)
        print(f"Generated {len([q for q in all_questions if q['category'] == category_name])} {category_name} questions")

    # Write to CSV with Unix line endings
    with open(output_file, 'w', newline='', encoding='utf-8') as f:
        writer = csv.writer(f, lineterminator='\n')
        writer.writerow(['id', 'category', 'level', 'text', 'answer1', 'answer2', 'answer3', 'answer4', 'answer5', 'correctAnswerIndex', 'hint'])

        for q in all_questions:
            writer.writerow([
                q['id'],
                q['category'],
                q['level'],
                q['text'],
                q['answers'][0],
                q['answers'][1],
                q['answers'][2],
                q['answers'][3],
                q['answers'][4],
                q['correct_idx'],
                q['hint']
            ])

    print(f"\nFile saved: {output_file}")
    print(f"Questions generated: {len(all_questions)}")
    print(f"Categories complete: {len(categories)} of 10")
    print(f"Target: 5000 questions (10 categories × 500 questions each)")
    print("\nCompleted categories: Biology, Geography, Math, Science, Technology, History")
    print("Remaining categories needed: Space, Food, Language, Earth")

if __name__ == '__main__':
    main()
